+  const dir = join(home, ".claude", "open-brain", "hook-claims");
+  let names: string[];
+  try {
+    names = readdirSync(dir);
+  } catch (err) {
+    if (errno(err) === "ENOENT") return;
+    throw err;
+  }
+  const now = Date.now();
+  let removed = 0;
+  for (const name of names) {
+    if (removed >= SWEEP_CAP) break;
+    const p = join(dir, name);
+    if (p === keep) continue;
+    try {
